INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (3287, 'a.yml', 'DEFAULT_GROUP', 'a=abc', '1c8128107bd726f312947b043e28572a', '2026-02-28 07:44:31', '2026-02-28 07:45:11', 'nacos', '172.18.0.1', '', '75bc1675-1e8e-4099-b2f2-d9482ce14f4e', '', '', '', 'properties', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5550, 'boot-datasource.yml', 'DEFAULT_GROUP', 'spring: \n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-basic-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${environment}-db}?useSSL=false&serverTimezone=UTC&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    hikari:\n      maximum-pool-size: 12\n      connection-timeout: 6000\n      minimum-idle: 12\n      idle-timeout: 500000\n      max-lifetime: 540000\n      connection-test-query: SELECT 1', 'f015bf7768bef8f62262a33ea75055ea', '2026-07-03 13:54:34', '2026-07-08 08:44:11', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5551, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', 'spring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', '488145c960b14d62df086865f533cc4a', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5552, 'boot-job.yml', 'DEFAULT_GROUP', 'xxl: \r\n  job: \r\n    accessToken: \"\"\r\n    admin: \r\n      addresses: http://localhost:8080/xxl-job-admin\r\n    executor: \r\n      appname: ${spring.application.name}\r\n      address: \"\"\r\n      ip: \"\"\r\n      port: 0\r\n      logpath: ./data/xxl-job\r\n      logretentiondays: 30', '064ce91193b5e89d015c31390f3bf584', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5553, 'boot-redis.yml', 'DEFAULT_GROUP', 'spring: \n  data: \n    redis: \n      host: maozi-cloud-basic-redis\n      port: 6379\n      password: 812840531zhang\n      lettuce:\n        shutdown-timeout: 300ms\n        pool:\n          max-active: 600\n          max-wait: 1000\n          max-idle: 300\n          min-idle: 0\n        timeout: 60000\n#    cluster:\n#      nodes: \n#        - 192.168.1.111:7001\n#        - 192.168.1.112:7001\n#        - 192.168.1.110:7002\n#        - 192.168.1.110:7001\n#        - 192.168.1.111:7002\n#        - 192.168.1.112:7001', '3b31a4357e97ad0aa935c34f658e0493', '2026-07-03 13:54:34', '2026-07-08 08:44:51', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5554, 'boot-seata.yml', 'DEFAULT_GROUP', 'spring:\n  cloud:\n    alibaba:\n      seata:\n        # 自定义事务组名称 tx_group，需要与服务端一致\n        tx-service-group: tx-group\n\nseata:\n  enabled: true\n  application-id: ${spring.application.name}\n  tx-service-group: tx-group\n  service:\n   vgroup-mapping:\n     tx-group: tx-group\n  config:\n    type: nacos\n    nacos:\n      namespace: public\n      serverAddr: localhost:8848\n      group: SEATA_GROUP\n      username: nacos\n      password: nacos\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: localhost:8848\n      group : SEATA_GROUP\n      namespace: public\n      username: nacos\n      password: nacos', 'cc49ebc81b7592d60a884d0a8f643155', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL);
