INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5639, 'transport.type', 'SEATA_GROUP', 'TCP', 'b136ef5f6a01d816991fe3cf7a6ac763', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'text', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5640, 'maozi-etc-sentinel.yml', 'DEFAULT_GROUP', '#spring settings\nspring.http.encoding.force=true\nspring.http.encoding.charset=UTF-8\nspring.http.encoding.enabled=true\n#server.port=9000\n\n#cookie name setting\nserver.servlet.session.cookie.name=sentinel_dashboard_cookie\n\n#logging settings\nlogging.level.org.springframework.web=INFO\nlogging.file=${user.home}/logs/csp/sentinel-dashboard.log\nlogging.pattern.file= %d{yyyy-MM-dd HH:mm:ss} [%thread] %-5level %logger{36} - %msg%n\n#logging.pattern.console= %d{yyyy-MM-dd HH:mm:ss} [%thread] %-5level %logger{36} - %msg%n\n\n#auth settings\nauth.filter.exclude-urls=/,/auth/login,/auth/logout,/registry/machine,/version\nauth.filter.exclude-url-suffixes=htm,html,js,css,map,ico,ttf,woff,png\n# If auth.enabled=false, Sentinel console disable login\nauth.username=sentinel\nauth.password=sentinel\n\n# Inject the dashboard version. It\'s required to enable\n# filtering in pom.xml for this resource file.\nsentinel.dashboard.version=${project.version}\n\n\n\n\n\n\n\n\n\n\n\n\nspring.datasource.driver-class-name=com.mysql.jdbc.Driver\nspring.datasource.url=\nspring.datasource.username=\nspring.datasource.password=\n\n# spring data jpa\nspring.jpa.hibernate.ddl-auto=none\nspring.jpa.hibernate.use-new-id-generator-mappings=false\nspring.jpa.database-platform=org.hibernate.dialect.MySQLDialect\nspring.jpa.show-sql=false\n', '29789c2a9b259d55f95b3f2b0f44a498', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5641, 'saas-param-error.json', 'DEFAULT_GROUP', '{\n    \"orderId\":\"订单\",\n    \"memberId\":\"客户\",\n    \"promoteId\":\"推广\",\n    \"day\":\"天数\",\n    \"labelId\":\"标签\",\n    \"userId\":\"用户\",\n    \"username\":\"用户名\",\n    \"password\":\"密码\",\n    \"messageId\":\"消息\",\n    \"roleId\":\"角色\",\n    \"compareCredentialsImage\":\"比价凭证\",\n    \"orderValuationId\":\"报价单\",\n    \"assessorAmount\":\"报价价格\",\n    \"storesId\":\"门店\",\n    \"city\":\"城市\",\n    \"query\":\"关键字\",\n    \"region\":\"城市\"\n}', '57ddd9c3a95d95c80023360aa916a225', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'json', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5642, 'boot-arthas.yml', 'DEFAULT_GROUP', 'arthas: \n  agent-id: ${spring.application.name}\n  tunnel-server: ws://localhost:7777/ws\n  telnet-port: -1\n  http-port: -1', '643c917b51311cefa55fb225a7b0cb2b', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5643, 'boot-lock.yml', 'DEFAULT_GROUP', 'spring:\n  lock:\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    database: ${spring.data.redis.database:0}\n    #waitTime: 60 #获取锁最长阻塞时间（默认：60，单位：秒）\n    #leaseTime: 60 #已获取锁后自动释放时间（默认：60，单位：秒）\n    #redis集群配置 如 redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    #spring.klock.address 和 spring.klock.cluster-server.node-addresses 选其一即可\n    #cluster-server.node-addresses:', '1b41138ceeb9733a9ee3c6ab3e83fb0e', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5644, 'boot-monitor.yml', 'DEFAULT_GROUP', 'spring:  \n  security:\n    user:\n      name: admin\n      password: admin\n  boot: \n    admin: \n      discovery: \n        services: maozi-cloud-*\n      client:\n        # url: http://localhost:8000\n        username: admin\n        password: admin\n        # auto-deregistration: true\n        # instance: \n        #   prefer-ip: true\n        #   metadata: \n        #     tags: \n        #       environment: 本地\n\nendpoints:\n  dubbo:\n    enabled: true\n\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${environment}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${environment}', 'e2a2321c6649934dd4425964b0101527', '2026-07-03 13:54:34', '2026-07-04 04:27:23', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5645, 'cloud-oauth.yml', 'DEFAULT_GROUP', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          # mode: http\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456', '77e5f1492fd39d65cead251a27a4abea', '2026-07-03 13:54:34', '2026-07-08 20:20:30', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5646, 'boot-db.yml', 'DEFAULT_GROUP', 'mybatis-plus:\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  configuration: \n    map-underscore-to-camel-case: true\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config: \n    refresh: false\n    banner: false\n    db-config:\n      db-type: mysql\n      id-type: AUTO\n      field-strategy: NOT_NULL\n      column-like: false\n      capital-mode: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nmybatis-plus-join:\n  banner: false\n  table-alias: main\n\nmybatis:\n  configuration:\n    cache-enabled: false\n\nspring: \n  flyway: \n    enabled: true\n    table: system_table_flyway\n    clean-disabled: true\n    out-of-order: true\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db\n    encoding: UTF-8', '6b82a3996631502d935dd3831737dd42', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5647, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', 'project:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\napplication-port: ${application-dev-port:4000}\napplication-dubbo-port: ${application-dev-dubbo-port:20881}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\napplication-project-system: \n  projectName: 小猫子\n  corporationName: 小猫子\n  icon: http://dummyimage.com/100x100\n  environment: ${project.environment}\n  description: 小猫子个人脚手架\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭', '78cd8c7905c7d53de038dbeda5581b95', '2026-07-03 13:54:34', '2026-07-04 05:15:42', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5648, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', 'project:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\napplication-port: ${application-dev-port:3000}\napplication-dubbo-port: ${application-dev-dubbo-port:20880}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-local-db\n\napplication-redis-database: 3\n\n# application-project-whitelist: ', 'f935fd0f9f09aae31b732bf292de4e6b', '2026-07-03 13:54:34', '2026-07-04 05:16:03', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5649, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', 'project:\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\napplication-port: ${application-dev-port:1000}\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          series: INFORMATIONAL\n          exceptions: java.net.ConnectException,org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM-SERVICE\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH-SERVICE\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', 'aacc1015ac4651f0eb2f0a2c0067647b', '2026-07-03 13:54:34', '2026-07-05 06:18:35', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5650, 'maozi-cloud-monitor-service.yml', 'DEFAULT_GROUP', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\napplication-port: ${application-dev-port:2000}\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      # ui:\n      #   external-views:\n\n      #     - label: \"Nacos\"\n      #       url: \"http://localhost:8848/nacos\"\n      #       iframe: true\n      #       order: 2002\n\n      #     - label: \"Grafana\"\n      #       url: \"http://maozi-cloud-grafana:3300\"\n      #       iframe: true\n      #       order: 2004\n\n      #     - label: \"Arthas\"\n      #       url: \"http://localhost:9080\"\n      #       iframe: true\n      #       order: 2005', 'b1c76edb1e568732b889d665b18e8c77', '2026-07-03 13:54:44', '2026-07-03 13:54:44', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5772, 'boot-datasource.yml', 'DEFAULT_GROUP', 'spring: \n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-basic-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${environment}-db}?useSSL=false&serverTimezone=UTC&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    hikari:\n      maximum-pool-size: 12\n      connection-timeout: 6000\n      minimum-idle: 12\n      idle-timeout: 500000\n      max-lifetime: 540000\n      connection-test-query: SELECT 1', 'f015bf7768bef8f62262a33ea75055ea', '2026-07-03 14:33:55', '2026-07-08 08:46:44', 'nacos', '172.18.0.1', '', 'dev', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5773, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', 'spring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', '488145c960b14d62df086865f533cc4a', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5774, 'boot-job.yml', 'DEFAULT_GROUP', 'xxl: \r\n  job: \r\n    accessToken: \"\"\r\n    admin: \r\n      addresses: http://localhost:8080/xxl-job-admin\r\n    executor: \r\n      appname: ${spring.application.name}\r\n      address: \"\"\r\n      ip: \"\"\r\n      port: 0\r\n      logpath: ./data/xxl-job\r\n      logretentiondays: 30', '064ce91193b5e89d015c31390f3bf584', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5775, 'boot-redis.yml', 'DEFAULT_GROUP', 'spring: \n  data: \n    redis: \n      host: maozi-cloud-basic-redis\n      port: 6379\n      password: 812840531zhang\n      lettuce:\n        shutdown-timeout: 300ms\n        pool:\n          max-active: 600\n          max-wait: 1000\n          max-idle: 300\n          min-idle: 0\n        timeout: 60000\n#    cluster:\n#      nodes: \n#        - 192.168.1.111:7001\n#        - 192.168.1.112:7001\n#        - 192.168.1.110:7002\n#        - 192.168.1.110:7001\n#        - 192.168.1.111:7002\n#        - 192.168.1.112:7001', '3b31a4357e97ad0aa935c34f658e0493', '2026-07-03 14:33:55', '2026-07-08 08:46:59', 'nacos', '172.18.0.1', '', 'dev', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (5776, 'boot-seata.yml', 'DEFAULT_GROUP', 'spring:\n  cloud:\n    alibaba:\n      seata:\n        # 自定义事务组名称 tx_group，需要与服务端一致\n        tx-service-group: tx-group\n\nseata:\n  enabled: true\n  application-id: ${spring.application.name}\n  tx-service-group: tx-group\n  service:\n   vgroup-mapping:\n     tx-group: tx-group\n  config:\n    type: nacos\n    nacos:\n      namespace: public\n      serverAddr: localhost:8848\n      group: SEATA_GROUP\n      username: nacos\n      password: nacos\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: localhost:8848\n      group : SEATA_GROUP\n      namespace: public\n      username: nacos\n      password: nacos', 'cc49ebc81b7592d60a884d0a8f643155', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL);
