INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1483, 4601, 'maozi-cloud-monitor.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\napplication-port: ${application-dev-port:8000}\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n      \n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      ui:\n        external-views:\n        \n          - label: \"注册中心\"\n            url: \"http://maozi-cloud-nacos:8848/nacos/#/configurationManagement?dataId=&group=&appName=&namespace=&pageSize=&pageNo=\"\n            iframe: true\n            order: 2002\n\n          - label: \"接口文档\"\n            url: \"https://localhost:10000/doc.html\"\n            iframe: true\n            order: 2003\n\n          - label: \"容器管理\"\n            url: \"http://localhost:9000\"\n            iframe: true\n            order: 2004\n\n          - label: \"Arthas管理\"\n            url: \"http://localhost:9080\"\n            iframe: true\n            order: 2005', '71dec651b647f8507ae60f65686f78a1', '2026-06-11 02:32:58', '2026-06-11 10:32:59', 'nacos', '172.18.0.1', 'U', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1483, 4602, 'maozi-cloud-monitor.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\napplication-port: ${application-dev-port:8000}\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n      \n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      ui:\n        external-views:\n        \n          - label: \"注册中心\"\n            url: \"http://localhost:8848/nacos/#/configurationManagement?serverId=center&group=&dataId=&namespace=&pageSize=&pageNo=&appName=\"\n            iframe: true\n            order: 2002\n\n          - label: \"接口文档\"\n            url: \"https://localhost:10000/doc.html\"\n            iframe: true\n            order: 2003\n\n          - label: \"容器管理\"\n            url: \"http://localhost:9000\"\n            iframe: true\n            order: 2004\n\n          - label: \"Arthas管理\"\n            url: \"http://localhost:9080\"\n            iframe: true\n            order: 2005', '114f6cbdd9db19fd31620f383347b7a4', '2026-06-11 02:33:23', '2026-06-11 10:33:24', 'nacos', '172.18.0.1', 'U', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1483, 4603, 'maozi-cloud-monitor.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\napplication-port: ${application-dev-port:1000}\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n      \n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      ui:\n        external-views:\n        \n          - label: \"注册中心\"\n            url: \"http://localhost:8848/nacos/#/configurationManagement?serverId=center&group=&dataId=&namespace=&pageSize=&pageNo=&appName=\"\n            iframe: true\n            order: 2002\n\n          - label: \"容器管理\"\n            url: \"http://localhost:9000\"\n            iframe: true\n            order: 2004\n\n          - label: \"Arthas管理\"\n            url: \"http://localhost:9080\"\n            iframe: true\n            order: 2005', '1d7228685cb571deaa600eaa1a976fdf', '2026-06-11 02:33:32', '2026-06-11 10:33:32', 'nacos', '172.18.0.1', 'U', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (102, 4604, 'maozi-cloud-gateway.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\napplication-port: ${application-dev-port:10000}\n\napplication-project-name: gateway\n\nknife4j:\n  gateway:\n    enabled: true\n    strategy: discover\n    discover:\n      version: openapi3\n      enabled: true\n      excluded-services:\n        - dubbo.*\n        - maozi-cloud-monitor\n\nspring: \n  cloud:\n    sentinel:\n      filter:\n        enabled: false\n      datasource:\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            dataId: ${spring.application.name}-gw-flow\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            dataId: ${spring.application.name}-gw-api-group\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n    gateway:\n      discovery:\n        locator:\n          enabled: true\n\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: GET,POST\n          statuses: BAD_GATEWAY,GATEWAY_TIMEOUT,SERVICE_UNAVAILABLE\n          series: INFORMATIONAL\n          exceptions: java.net.ConnectException,org.springframework.cloud.gateway.support.NotFoundException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth\n          predicates:\n          - Path=/oauth/**\n          # filters:\n          #- StripPrefix=1\n          # - WSProtocolFilter\n\n      # default-filters:\n      #   - name: Hystrix\n      #     args:\n      #       name: default\n      #       #转发地址\n      #       fallbackUri: \'forward:/fallback\'\n      #   - name: Retry\n      #     args:\n      #       #重试次数，默认值是 3 次\n      #       retries: 3\n      #       #HTTP 的状态返回码\n      #       statuses: BAD_GATEWAY,BAD_REQUEST\n      #       #指定哪些方法的请求需要进行重试逻辑，默认值是 GET 方法\n      #       methods: GET,POST', 'efdfdf29993f8af665df7ace985689b3', '2026-06-11 02:33:50', '2026-06-11 10:33:51', 'nacos', '172.18.0.1', 'U', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1520, 4605, 'cloud-oauth.yml', 'DEFAULT_GROUP', '', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # 匿名token自省端点\n          introspection-uri: http://127.0.0.1:1000/oauth2/introspect\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456\n\n# security:\n#   oauth2:\n#     client: \n#       client-id: system\n#       client-secret: 123456\n#       access-token-uri: http://maozi-cloud-oauth:1000/oauth/token\n#       user-authorization-uri: http://maozi-cloud-oauth:1000/oauth/authorize\n#     resource:\n#       type: dubbo\n#       user-info-uri: http', '48f97fbad63bd62a1c6a0573273d47b9', '2026-06-11 02:34:19', '2026-06-11 10:34:19', 'nacos', '172.18.0.1', 'U', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1497, 4606, 'maozi-cloud-oauth.yml', 'DEFAULT_GROUP', '', 'project:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\napplication-port: ${application-dev-port:1000}\napplication-dubbo-port: ${application-dev-dubbo-port:20880}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-localhost-db\n\napplication-redis-database: 3\n\napplication-project-whitelist: /oauth/check_token,/oauth/token/get,/oauth/token/refresh,/oauth/token/**/check,/oauth/token/**/destroy', '0ae7d63b37ac05a0d6fd1d09b62b9db3', '2026-06-11 02:34:34', '2026-06-11 10:34:35', 'nacos', '172.18.0.1', 'U', '');
