INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (120, 5539, 'maozi-cloud-form.yml', 'DEFAULT_GROUP', '', 'application-port: 4000\n\napplication-project-name: form\n\napplication-datasource-jdbc-url: localhost:3306/maozi_test\napplication-datasource-jdbc-username: root\napplication-datasource-jdbc-password: password\n\napplication-rpc-service-name: \n\napplication-project-whitelist: /sf/callback,/ss/callback,/**\n\nspring.cloud.stream.rocketmq.bindings: \n  FORM-TASK-UP-STATUS-OUTPUT: {producer.sync: true}\n\nspring.cloud.stream.bindings: \n\n  FORM-WAIT-CONFIRM-OUTPUT: {destination: FORM-WAIT-CONFIRM-TOPIC,content-type: application/json}\n  FORM-WAIT-CONFIRM-INPUT: {destination: FORM-WAIT-CONFIRM-TOPIC,content-type: application/json,group: FORM-WAIT-CONFIRM-GROUP,consumer.maxAttempts: 3}\n  \n  FORM-TASK-UP-STATUS-OUTPUT: {destination: FORM-TASK-UP-STATUS-TOPIC,content-type: application/json}\n  FORM-TASK-UP-STATUS-INPUT: {destination: FORM-TASK-UP-STATUS-TOPIC,content-type: application/json,group: FORM-TASK-UP-STATUS-GROUP,consumer.maxAttempts: 3}\n\n', 'd3b33e84cc33397ee75f9fd710520673', '2026-06-26 22:24:51', '2026-06-27 06:24:51', NULL, '192.168.65.1', 'D', '');
