INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (112, 5541, 'maozi-cloud-message.yml', 'DEFAULT_GROUP', '', 'application-port: 5000\n\napplication-project-name: message\n\napplication-datasource-jdbc-url: localhost:3306/maozi-test-db\napplication-datasource-jdbc-username: root\napplication-datasource-jdbc-password: password\n\napplication-rpc-service-name: \n\napplication-project-whitelist: /ws/message,/ws/sockjs/message,/**\n\n# RocketMQConsumerProperties\nspring.cloud.stream.bindings: \n\n  WS-USER-MESSAGE-OUTPUT: {destination: WS-USER-MESSAGE-TOPIC,content-type: application/json}\n  WS-USER-MESSAGE-INPUT: {destination: WS-USER-MESSAGE-TOPIC,content-type: application/json,group: WS-USER-MESSAGE-TOPIC-GROUP,consumer: {broadcasting: true}}\n\n  WS-USER-MESSAGE-PERMISSION-OUTPUT: {destination: WS-USER-MESSAGE-PERMISSION-TOPIC,content-type: application/json}\n  WS-USER-MESSAGE-PERMISSION-INPUT: {destination: WS-USER-MESSAGE-PERMISSION-TOPIC,content-type: application/json,group: WS-USER-MESSAGE-PERMISSION-TOPIC-GROUP,consumer: {broadcasting: true}}', '23d19bdb7c4e85738c9e99f04d68f0b2', '2026-06-26 22:25:06', '2026-06-27 06:25:07', NULL, '192.168.65.1', 'D', '');
