INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (100, 5543, 'saas-code.json', 'DEFAULT_GROUP', '', '{\n    \"maozi-cloud-base-code\": {\n        \"1\": {\n            \"code\": 1,\n            \"message\": \"\"\n        },\n        \"2\": {\n            \"code\": 2,\n            \"message\": \"服务没有此code\"\n        },\n        \"3\": {\n            \"code\": 3,\n            \"message\": \"Token错误\"\n        },\n        \"6\": {\n            \"code\": 6,\n            \"message\": \"服务未启动\"\n        },\n        \"7\": {\n            \"code\": 7,\n            \"message\": \"更新失败\"\n        },\n        \"8\": {\n            \"code\": 8,\n            \"message\": \"添加失败\"\n        },\n        \"9\": {\n            \"code\": 9,\n            \"message\": \"删除失败\"\n        },\n        \"10\": {\n            \"code\": 10,\n            \"message\": \"分页参数错误\"\n        },\n        \"11\": {\n            \"code\": 11,\n            \"message\": \"游客\"\n        },\n        \"12\": {\n            \"code\": 12,\n            \"message\": \"验签失败\"\n        },\n        \"13\": {\n            \"code\": 13,\n            \"message\": \"验证失败\"\n        },\n        \"14\": {\n            \"code\": 14,\n            \"message\": \"字段全部为空\"\n        },\n        \"16\": {\n            \"code\": 16,\n            \"message\": \"重复提交错误\"\n        },\n        \"17\": {\n            \"code\": 17,\n            \"message\": \"未找到第三方接口转换器\"\n        },\n        \"18\": {\n            \"code\": 18,\n            \"message\": \"未找到第三方数据请求转换器\"\n        },\n        \"400\": {\n            \"code\": 400,\n            \"message\": \"参数错误\"\n        },\n        \"401\": {\n            \"code\": 401,\n            \"message\": \"用户未授权\"\n        },\n        \"402\": {\n            \"code\": 402,\n            \"message\": \"恶意请求\"\n        },\n        \"403\": {\n            \"code\": 403,\n            \"message\": \"权限不足\"\n        },\n        \"404\": {\n            \"code\": 404,\n            \"message\": \"没有此资源\"\n        },\n        \"405\": {\n            \"code\": 405,\n            \"message\": \"请求格式错误\"\n        },\n        \"415\": {\n            \"code\": 415,\n            \"message\": \"请求格式错误\"\n        },\n        \"500\": {\n            \"code\": 500,\n            \"message\": \"内部服务错误\"\n        },\n        \"600\": {\n            \"code\": 600,\n            \"message\": \"错误熔断\"\n        },\n        \"601\": {\n            \"code\": 601,\n            \"message\": \"限流中\"\n        },\n        \"700\": {\n            \"code\": 700,\n            \"message\": \"网关错误\"\n        },\n        \"800\": {\n            \"code\": 800,\n            \"message\": \"获取Token失败\"\n        }\n    },\n    \"maozi-cloud-test-service-test-code\":{\n        \"3001\":{\n            \"code\":3001,\n            \"message\":\"测试测试\"\n        }\n    },\n    \"maozi-cloud-test-service-test-enums\":{\n\n        \"test-enums\":[{\n            \"key\": 0,\n            \"value\": \"test11\"\n        },{\n            \"key\": 1,\n            \"value\": \"test22\"\n        }]\n        \n    },\n    \"maozi-cloud-sso-service-oauthToken-rpc-code\":{\n        \"1001\":{\n            \"code\":1001,\n            \"message\":\"client无效\"\n        },\n        \"1002\":{\n            \"code\":1002,\n            \"message\":\"用户或密码错误\"\n        }\n    }\n}', 'd6eeafb40fe45564f55754adc9b9a69e', '2026-06-26 22:25:45', '2026-06-27 06:25:45', NULL, '192.168.65.1', 'D', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (95, 5544, 'maozi-etc-user-mq-consume.yml', 'DEFAULT_GROUP', '', 'application-port: 60000\n\napplication-project-name: user-mq-consume\n\n\n\nspring:\n  cloud:\n    stream:\n      rocketmq: \n      # BindingProperties \n        bindings:\n          maozi-log-topic: {consumer.orderly: true}\n      bindings: { \n\n        maozi-log-topic: {\n          destination: maozi-log-topic, \n          content-type: text/plain, \n          group: maozi-log-group,\n          # RocketMQConsumerProperties \n          consumer.maxAttempts: 3,\n          }\n\n         }\n  \n\n        \n\n\n', 'bccef6e7f008feb6e1f3f7ec981a0910', '2026-06-26 22:25:51', '2026-06-27 06:25:51', NULL, '192.168.65.1', 'D', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1519, 5545, 'boot-monitor.yml', 'DEFAULT_GROUP', '', 'spring:  \r\n  security:\r\n    user:\r\n      name: admin\r\n      password: admin\r\n  boot: \r\n    admin: \r\n      discovery: \r\n        services: maozi-cloud-*\r\n      client:\r\n        # url: http://localhost:8000\r\n        username: admin\r\n        password: admin\r\n        # auto-deregistration: true\r\n        # instance: \r\n        #   prefer-ip: true\r\n        #   metadata: \r\n        #     tags: \r\n        #       environment: 本地\r\n\r\nendpoints:\r\n  dubbo:\r\n    enabled: true\r\n\r\nmanagement:\r\n  info.env.enabled: true\r\n  health:\r\n    dubbo:\r\n      status:\r\n        defaults: memory\r\n        extras: load,threadpool\r\n  endpoints:\r\n    web:\r\n      exposure:\r\n        include: \'*\'\r\n  endpoint:\r\n    dubbo:\r\n      enabled: true\r\n    dubbo-shutdown:\r\n      enabled: true\r\n    dubbo-configs:\r\n      enabled: true\r\n    dubbo-services:\r\n      enabled: true\r\n    dubbo-references:\r\n      enabled: true\r\n    dubbo-properties:\r\n      enabled: true\r\n    health:\r\n      show-details: ALWAYS\r\n      probes.enabled: true', '6d9bdb9efc506c1238d1f1541f54c004', '2026-07-01 22:59:34', '2026-07-02 06:59:35', 'nacos', '172.18.0.1', 'U', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1520, 5546, 'cloud-oauth.yml', 'DEFAULT_GROUP', '', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          mode: rpc\n          # 匿名token自省端点\n          introspection-uri: http://127.0.0.1:3000/oauth2/introspect\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456\n\n# security:\n#   oauth2:\n#     client: \n#       client-id: system\n#       client-secret: 123456\n#       access-token-uri: http://maozi-cloud-oauth:1000/oauth/token\n#       user-authorization-uri: http://maozi-cloud-oauth:1000/oauth/authorize\n#     resource:\n#       type: dubbo\n#       user-info-uri: http', '65373da480d0f659086512055267d9f0', '2026-07-01 22:59:56', '2026-07-02 06:59:56', 'nacos', '172.18.0.1', 'U', '');
