INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (1519, 5570, 'boot-monitor.yml', 'DEFAULT_GROUP', '', 'spring:  \n  security:\n    user:\n      name: admin\n      password: admin\n  boot: \n    admin: \n      discovery: \n        services: maozi-cloud-*\n      client:\n        # url: http://localhost:8000\n        username: admin\n        password: admin\n        # auto-deregistration: true\n        # instance: \n        #   prefer-ip: true\n        #   metadata: \n        #     tags: \n        #       environment: 本地\n\nendpoints:\n  dubbo:\n    enabled: true\n\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${spring.profiles.active}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${spring.profiles.active}', '7433f244ea832df9617cb6cbb587cd31', '2026-07-01 23:21:19', '2026-07-02 07:21:20', 'nacos', '172.18.0.1', 'U', '');
