INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (27, 5867, 'cloud-default.yml', 'DEFAULT_GROUP', '', 'project: \n  environment: ${environment:local}\n\nserver:\n  port: ${application-port}\n  error.path: /application/error\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring: \n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF\n    com.xxl.job.core.handler.impl.MethodJobHandler: INFO\n    org.springframework.cloud.stream.binding.StreamListenerMessageHandler: INFO', 'daca8730b5bd7e144b199c7a44588bd0', '2026-07-03 06:25:29', '2026-07-03 14:25:29', NULL, '172.18.0.1', 'D', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (28, 5868, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '', 'dubbo:\n  # registry.register-mode: instance/interface/all\n  application: \n    name: dubbo-${spring.application.name}\n    register-mode: instance\n    version: ${project.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${application-dubbo-port}\n  provider:\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 30000\n    retries: 0\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}\n', 'f4c08b2dc84b662658e8f47d25e5d444', '2026-07-03 06:25:29', '2026-07-03 14:25:29', NULL, '172.18.0.1', 'D', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (29, 5869, 'cloud-nacos.yml', 'DEFAULT_GROUP', '', 'spring: \n  cloud: \n    nacos: \n      discovery:\n        enabled: true\n        register-enabled: true\n        metadata: \n          version: ${project.version:main}', 'f5ac40346cba544f7835244e79311a79', '2026-07-03 06:25:29', '2026-07-03 14:25:29', NULL, '172.18.0.1', 'D', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (31, 5870, 'cloud-rocket.yml', 'DEFAULT_GROUP', '', 'spring:\n  cloud:\n    stream:\n      rocketmq:\n        binder:\n          # access-key: \n          # secret-key: \n          name-server: localhost:9876\n# rocketmq:\n  # instance:\n    # id: \n    # name: ', 'e01da9f5d2b141a256fb4baa9e8c32b3', '2026-07-03 06:25:29', '2026-07-03 14:25:29', NULL, '172.18.0.1', 'D', '');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (33, 5871, 'cloud-sentinel.yml', 'DEFAULT_GROUP', '', 'resttemplate:\n  sentinel:\n    enabled: true\n\nfeign:\n  sentinel: \n    enabled: true\n\nspring: \n  cloud: \n    sentinel:\n      eager: true\n      transport:\n        port: 8081\n        dashboard: localhost:8080\n      datasource:\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.application.name}-flow-rules\n            rule-type: flow\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.application.name}-degrade-rules\n            rule-type: degrade\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.application.name}-param-rules\n            rule-type: param-flow\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.application.name}-system-rules\n            rule-type: system\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: ${spring.cloud.nacos.config.namespace}\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.application.name}-authority-rules\n            rule-type: authority', '3adc7f9e573857015ecbb37cea6f70ac', '2026-07-03 06:25:29', '2026-07-03 14:25:29', NULL, '172.18.0.1', 'D', '');
