INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (5664, 6157, 'com.maozi.oauth.token.api.rpc.RpcOauthTokenService', 'mapping', '', 'dubbo-maozi-cloud-oauth-service', '0e3764c49fba5182223c875f125ce601', '2026-07-03 06:33:46', '2026-07-03 14:33:46', NULL, '172.18.0.1', 'D', 'local');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 6158, 'boot-datasource.yml', 'DEFAULT_GROUP', '', 'spring: \n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${environment}-db}?useSSL=false&serverTimezone=UTC&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    hikari:\n      maximum-pool-size: 12\n      connection-timeout: 6000\n      minimum-idle: 12\n      idle-timeout: 500000\n      max-lifetime: 540000\n      connection-test-query: SELECT 1', '7d06a5b57446e6bb923c6f33b8401dff', '2026-07-03 06:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', 'I', 'dev');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 6159, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', '', 'spring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', '488145c960b14d62df086865f533cc4a', '2026-07-03 06:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', 'I', 'dev');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 6160, 'boot-job.yml', 'DEFAULT_GROUP', '', 'xxl: \r\n  job: \r\n    accessToken: \"\"\r\n    admin: \r\n      addresses: http://localhost:8080/xxl-job-admin\r\n    executor: \r\n      appname: ${spring.application.name}\r\n      address: \"\"\r\n      ip: \"\"\r\n      port: 0\r\n      logpath: ./data/xxl-job\r\n      logretentiondays: 30', '064ce91193b5e89d015c31390f3bf584', '2026-07-03 06:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', 'I', 'dev');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 6161, 'boot-redis.yml', 'DEFAULT_GROUP', '', 'spring: \n  data: \n    redis: \n      host: maozi-cloud-redis\n      port: 6379\n      password: 812840531zhang\n      lettuce:\n        shutdown-timeout: 300ms\n        pool:\n          max-active: 600\n          max-wait: 1000\n          max-idle: 300\n          min-idle: 0\n        timeout: 60000\n#    cluster:\n#      nodes: \n#        - 192.168.1.111:7001\n#        - 192.168.1.112:7001\n#        - 192.168.1.110:7002\n#        - 192.168.1.110:7001\n#        - 192.168.1.111:7002\n#        - 192.168.1.112:7001', '25d46eef035609a153e96631a3ce6c5d', '2026-07-03 06:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', 'I', 'dev');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 6162, 'boot-seata.yml', 'DEFAULT_GROUP', '', 'spring:\n  cloud:\n    alibaba:\n      seata:\n        # 自定义事务组名称 tx_group，需要与服务端一致\n        tx-service-group: tx-group\n\nseata:\n  enabled: true\n  application-id: ${spring.application.name}\n  tx-service-group: tx-group\n  service:\n   vgroup-mapping:\n     tx-group: tx-group\n  config:\n    type: nacos\n    nacos:\n      namespace: public\n      serverAddr: localhost:8848\n      group: SEATA_GROUP\n      username: nacos\n      password: nacos\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: localhost:8848\n      group : SEATA_GROUP\n      namespace: public\n      username: nacos\n      password: nacos', 'cc49ebc81b7592d60a884d0a8f643155', '2026-07-03 06:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', 'I', 'dev');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (0, 6163, 'boot-swagger.yml', 'DEFAULT_GROUP', '', 'springdoc.api-docs.enabled: true\nswagger:\n  base-package: com.maozi.*.api.rest\n  title: \"${spring.application.name}服务\"\n  description: ${spring.application.name}\n  version: 1.0\n  terms-of-service-url: www.maozi.tech\n  authorization:\n    name: Authorization\n    key-name: Authorization\n    auth-regex: ^.*$\n  contact:\n    name: \"maozi\"\n    email: 1095071913@qq.com', '59b2e76158ec93c04df4e666f136cb5d', '2026-07-03 06:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', 'I', 'dev');
