INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (5866, 6319, 'boot-monitor.yml', 'DEFAULT_GROUP', '', 'spring:  \n  security:\n    user:\n      name: admin\n      password: admin\n  boot: \n    admin: \n      discovery: \n        services: maozi-cloud-*\n      client:\n        # url: http://localhost:8000\n        username: admin\n        password: admin\n        # auto-deregistration: true\n        # instance: \n        #   prefer-ip: true\n        #   metadata: \n        #     tags: \n        #       environment: 本地\n\nendpoints:\n  dubbo:\n    enabled: true\n\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${project.environment}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${project.environment}', 'e161cf5b47c58ac832cba17d2f4b680d', '2026-07-03 20:26:47', '2026-07-04 04:26:47', 'nacos', '172.18.0.1', 'U', 'dev');
