INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (5645, 6623, 'cloud-oauth.yml', 'DEFAULT_GROUP', '', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          mode: http\n          # 匿名token自省端点\n          introspection-uri: http://127.0.0.1:3000/oauth2/introspect\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456\n\n# security:\n#   oauth2:\n#     client: \n#       client-id: system\n#       client-secret: 123456\n#       access-token-uri: http://maozi-cloud-oauth:1000/oauth/token\n#       user-authorization-uri: http://maozi-cloud-oauth:1000/oauth/authorize\n#     resource:\n#       type: dubbo\n#       user-info-uri: http', 'ee5fbb677f51502269793520ab36e90e', '2026-07-08 11:33:01', '2026-07-08 19:33:02', 'nacos', '172.18.0.1', 'U', 'local');
