INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (5645, 6636, 'cloud-oauth.yml', 'DEFAULT_GROUP', '', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          mode: http\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456', '9fb13f8eff8e58a6d04765ceaa9030ef', '2026-07-08 11:49:43', '2026-07-08 19:49:43', 'nacos', '172.18.0.1', 'U', 'local');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`) VALUES (5867, 6637, 'cloud-oauth.yml', 'DEFAULT_GROUP', '', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          # mode: http\n          # 匿名token自省端点\n          introspection-uri: http://127.0.0.1:3000/oauth2/introspect\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456\n\n# security:\n#   oauth2:\n#     client: \n#       client-id: system\n#       client-secret: 123456\n#       access-token-uri: http://maozi-cloud-oauth:1000/oauth/token\n#       user-authorization-uri: http://maozi-cloud-oauth:1000/oauth/authorize\n#     resource:\n#       type: dubbo\n#       user-info-uri: http', 'a605eb73231cb8e55c8a2cfc17b50489', '2026-07-08 11:55:52', '2026-07-08 19:55:52', 'nacos', '172.18.0.1', 'U', 'dev');
